import { StyleFn } from "..";

export const Badge: StyleFn = (theme, mode) => {
  const { color, size, font } = theme;

  // alternative positions
  const bottomRightStyles = {
    bottom: 0,
    right: 0,
    top: "unset",
    left: "unset",
    transform: "translate(50%, 50%)",
  };
  const topRightStyles = {
    top: 0,
    right: 0,
    bottom: "unset",
    left: "unset",
    transform: "translate(50%, -50%)",
  };

  return {
    root: {
      display: "inline-block",
      position: "relative",
      // increased specificity for color variants
      "&$_info > $count, &$_info > $status": {
        color: color.text.neutral.minimal[mode],
        backgroundColor: color.surface.feedback.information.default[mode],
      },
      "&$_success > $count, &$_success > $status": {
        color: color.text.neutral.minimal[mode],
        backgroundColor: color.surface.feedback.success.default[mode],
      },
      "&$_warning > $count, &$_warning > $status": {
        color: color.text.feedback.warning.onsurface[mode],
        backgroundColor: color.surface.feedback.warning.default[mode],
      },
      "&$_error > $count, &$_error > $status": {
        color: color.text.neutral.minimal[mode],
        backgroundColor: color.surface.feedback.error.default[mode],
      },
    },
    count: {
      position: "absolute",
      ...topRightStyles,
      isolation: "isolate",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      whiteSpace: "nowrap",
      backgroundColor: color.palette.coolgrey[40],
      color: color.text.feedback.warning.onsurface[mode],
      fontSize: font.size.small,
      fontWeight: font.weight.bold,
      minWidth: size.spacing[16],
      minHeight: size.spacing[16],
      lineHeight: size.spacing[16],
      borderRadius: size.spacing[16],
      boxShadow: `0 0 0 2px ${color.border.neutral.minimal[mode]}`,
      padding: `0 ${size.spacing[3]}`,
    },
    status: {
      position: "absolute",
      ...bottomRightStyles,
      isolation: "isolate",
      backgroundColor: color.surface.componentonbackground.strong[mode],
      width: size.spacing[6],
      height: size.spacing[6],
      padding: 0,
      borderRadius: size.spacing[6],
      boxShadow: `0 0 0 1px ${color.border.neutral.minimal[mode]}`,
    },
    _info: {},
    _success: {},
    _warning: {},
    _error: {},
    _bottomright: {
      "& $count, &$status": bottomRightStyles,
    },
    _topright: {
      "& $count, &$status": topRightStyles,
    },
    _bottomleft: {
      "& $count, &$status": {
        bottom: 0,
        left: 0,
        top: "unset",
        right: "unset",
        transform: "translate(-50%, 50%)",
      },
    },
    _topleft: {
      "& $count, &$status": {
        top: 0,
        left: 0,
        bottom: "unset",
        right: "unset",
        transform: "translate(-50%, -50%)",
      },
    },
  };
};
